int printf(const char *format, ...);

struct account {
    char kind;
    int balance;
    short code;
    double rate;
    const char *label;
};

int bump(struct account *a, int by) {
    a->balance += by;
    return a->balance;
}

int sum_balances(const struct account *list, int count) {
    int sum = 0;
    for (int i = 0; i < count; i++) sum += list[i].balance;
    return sum;
}

int tag(const struct account *a) {
    if (a->kind == 'l') return -a->code;
    return a->code;
}

double projected(const struct account *a) {
    return a->balance * a->rate;
}

int label_length(const struct account *a) {
    int n = 0;
    while (a->label[n]) n++;
    return n;
}

int main(void) {
    struct account rows[3] = {
        { 'c', 100, 7, 0.5, "cash" },
        { 's', 250, 9, 1.25, "savings" },
        { 'l', -40, 3, 2.0, "loan" },
    };
    printf("sizeof %lu align %lu\n", (unsigned long)sizeof(struct account), (unsigned long)_Alignof(struct account));
    printf("kind %lu balance %lu code %lu rate %lu label %lu\n",
           (unsigned long)__builtin_offsetof(struct account, kind),
           (unsigned long)__builtin_offsetof(struct account, balance),
           (unsigned long)__builtin_offsetof(struct account, code),
           (unsigned long)__builtin_offsetof(struct account, rate),
           (unsigned long)__builtin_offsetof(struct account, label));
    bump(&rows[1], 5);
    printf("sum %d tag %d projected %g label_length %d\n", sum_balances(rows, 3), tag(&rows[2]), projected(&rows[1]), label_length(&rows[1]));
    return 0;
}

import ghidra.app.script.GhidraScript;
import ghidra.app.decompiler.DecompInterface;
import ghidra.app.decompiler.DecompileResults;
import ghidra.program.model.data.DataType;
import ghidra.program.model.data.Structure;
import ghidra.program.model.data.DataTypeComponent;
import ghidra.program.model.listing.Function;
import java.util.Iterator;

public class ListTypes extends GhidraScript {
    @Override
    public void run() throws Exception {
        Iterator<DataType> it = currentProgram.getDataTypeManager().getAllDataTypes();
        while (it.hasNext()) {
            DataType dt = it.next();
            if (dt instanceof Structure) {
                Structure s = (Structure) dt;
                println("STRUCT " + s.getPathName() + " size=" + s.getLength() + " align=" + s.getAlignment());
                for (DataTypeComponent c : s.getDefinedComponents()) {
                    println("  +" + c.getOffset() + " " + c.getDataType().getName() + " " + c.getFieldName());
                }
            }
        }
        DecompInterface d = new DecompInterface();
        d.openProgram(currentProgram);
        for (Function f : currentProgram.getFunctionManager().getFunctions(true)) {
            String name = f.getName();
            if (!name.equals("bump") && !name.equals("sum_balances") && !name.equals("tag") && !name.equals("projected") && !name.equals("label_length")) continue;
            println("SIG " + f.getPrototypeString(true, false));
            DecompileResults r = d.decompileFunction(f, 60, monitor);
            if (r.decompileCompleted()) {
                for (String line : r.getDecompiledFunction().getC().split("\n")) println("C " + line);
            } else {
                println("DECOMPILE FAILED " + r.getErrorMessage());
            }
        }
        d.dispose();
    }
}

import sys

from elftools.elf.elffile import ELFFile


def type_name(die):
    tag = die.tag
    if tag == "DW_TAG_base_type":
        return die.attributes["DW_AT_name"].value.decode()
    if tag == "DW_TAG_structure_type":
        return die.attributes["DW_AT_name"].value.decode()
    inner = die.get_DIE_from_attribute("DW_AT_type") if "DW_AT_type" in die.attributes else None
    if tag == "DW_TAG_pointer_type":
        return (type_name(inner) if inner else "void") + " *"
    if tag == "DW_TAG_const_type":
        return "const " + type_name(inner)
    return tag


def main(path):
    with open(path, "rb") as handle:
        elf = ELFFile(handle)
        dwarf = elf.get_dwarf_info()
        for unit in dwarf.iter_CUs():
            header = unit.header
            print(f"unit version {header['version']} unit_type {header['unit_type']} address_size {header['address_size']}")
            for die in unit.iter_DIEs():
                if die.tag != "DW_TAG_structure_type":
                    continue
                name = die.attributes["DW_AT_name"].value.decode()
                size = die.attributes["DW_AT_byte_size"].value
                print(f"struct {name} byte_size {size}")
                for child in die.iter_children():
                    if child.tag != "DW_TAG_member":
                        continue
                    member = child.attributes["DW_AT_name"].value.decode()
                    offset = child.attributes["DW_AT_data_member_location"].value
                    kind = child.get_DIE_from_attribute("DW_AT_type")
                    print(f"  +{offset} {type_name(kind)} {member}")


if __name__ == "__main__":
    main(sys.argv[1])

extern "C" int printf(const char *format, ...);

struct Shape {
    virtual ~Shape() {}
    virtual int area() const = 0;
    virtual const char *name() const { return "shape"; }
};

struct Rect : Shape {
    int w, h;
    Rect(int w_, int h_) : w(w_), h(h_) {}
    int area() const override { return w * h; }
    const char *name() const override { return "rect"; }
};

int describe(const Shape &s, int scale) {
    return s.area() * scale;
}

int main() {
    Rect r(3, 4);
    printf("%s %d\n", r.name(), describe(r, 2));
    return 0;
}

